const docChildren = [];

function run(text, options = {}) {
  return new TextRun({
    text,
    font: 'Times New Roman',
    size: options.size || 28,
    bold: options.bold,
    italics: options.italics,
    break: options.break,
    allCaps: options.allCaps,
  });
}

function para(text = '', options = {}) {
  return new Paragraph({
    children: Array.isArray(text) ? text : [run(text, options.run || {})],
    alignment: options.alignment || AlignmentType.JUSTIFIED,
    indent: options.noIndent ? {} : { firstLine: 709 },
    spacing: options.spacing || { line: 360, after: 120 },
    heading: options.heading,
    pageBreakBefore: options.pageBreakBefore,
  });
}

function centered(text, options = {}) {
  return para(text, {
    alignment: AlignmentType.CENTER,
    noIndent: true,
    spacing: options.spacing || { line: 360, after: 120 },
    run: { bold: options.bold, size: options.size || 28, allCaps: options.allCaps },
  });
}

function right(text, options = {}) {
  return para(text, {
    alignment: AlignmentType.RIGHT,
    noIndent: true,
    spacing: options.spacing || { line: 360, after: 80 },
    run: { size: options.size || 28, bold: options.bold },
  });
}

function h1(title) {
  return new Paragraph({
    text: title,
    heading: HeadingLevel.HEADING_1,
    alignment: AlignmentType.CENTER,
    spacing: { line: 360, before: 240, after: 240 },
  });
}

function h2(title) {
  return new Paragraph({
    text: title,
    heading: HeadingLevel.HEADING_2,
    alignment: AlignmentType.LEFT,
    spacing: { line: 360, before: 180, after: 160 },
  });
}

function h3(title) {
  return new Paragraph({
    text: title,
    heading: HeadingLevel.HEADING_3,
    alignment: AlignmentType.LEFT,
    spacing: { line: 360, before: 120, after: 120 },
  });
}

function br() {
  return new Paragraph({ children: [new PageBreak()] });
}

function bullet(text) {
  return new Paragraph({
    children: [run(text)],
    bullet: { level: 0 },
    spacing: { line: 360, after: 80 },
  });
}

function cell(text, options = {}) {
  const children = Array.isArray(text)
    ? text.map((item) => para(item, { noIndent: true, spacing: { line: 280, after: 60 } }))
    : [para(text, { noIndent: true, spacing: { line: 280, after: 60 }, run: { bold: options.bold, size: options.size || 24 } })];
  return new TableCell({
    children,
    shading: options.shading ? { fill: options.shading } : undefined,
    margins: { top: 80, bottom: 80, left: 80, right: 80 },
    borders: {
      top: { style: BorderStyle.SINGLE, size: 1, color: '9AAE9D' },
      bottom: { style: BorderStyle.SINGLE, size: 1, color: '9AAE9D' },
      left: { style: BorderStyle.SINGLE, size: 1, color: '9AAE9D' },
      right: { style: BorderStyle.SINGLE, size: 1, color: '9AAE9D' },
    },
  });
}

function tableCaption(number, title) {
  return para(`Ð¢Ð°Ð±Ð»Ð¸Ñ†Ð° ${number} - ${title}`, {
    alignment: AlignmentType.LEFT,
    noIndent: true,
    spacing: { line: 360, before: 160, after: 80 },
  });
}

function makeTable(rows, widths) {
  return new Table({
    width: { size: 100, type: WidthType.PERCENTAGE },
    rows: rows.map((row, rowIndex) =>
      new TableRow({
        children: row.map((value, cellIndex) =>
          cell(value, {
            bold: rowIndex === 0,
            shading: rowIndex === 0 ? 'EEF4EA' : undefined,
            width: widths ? widths[cellIndex] : undefined,
          })
        ),
      })
    ),
  });
}

function figureCaption(number, title) {
  return centered(`Ð Ð¸ÑÑƒÐ½Ð¾Ðº ${number} - ${title}`, {
    size: 28,
    spacing: { line: 360, before: 80, after: 160 },
  });
}

function pngSize(buffer) {
  if (buffer.toString('ascii', 1, 4) !== 'PNG') return { width: 1366, height: 768 };
  return {
    width: buffer.readUInt32BE(16),
    height: buffer.readUInt32BE(20),
  };
}

function imageFigure(fileName, number, title, maxWidth = 510) {
  const file = path.join(screenshotDir, fileName);
  if (!fs.existsSync(file)) {
    return [centered(`[Ð¡ÐºÑ€Ð¸Ð½ÑˆÐ¾Ñ‚ ${fileName} Ð½Ðµ Ð½Ð°Ð¹Ð´ÐµÐ½]`), figureCaption(number, title)];
  }
  const data = fs.readFileSync(file);
  const size = pngSize(data);
  const width = Math.min(maxWidth, size.width);
  const height = Math.round((size.height / size.width) * width);
  return [
    new Paragraph({
      alignment: AlignmentType.CENTER,
      children: [
        new ImageRun({
          data,
          transformation: { width, height },
          type: 'png',
        }),
      ],
      spacing: { before: 120, after: 60 },
    }),
    figureCaption(number, title),
  ];
}

function diagramFigure(number, title, rows) {
  const table = new Table({
    width: { size: 100, type: WidthType.PERCENTAGE },
    rows: rows.map((row) =>
      new TableRow({
        children: row.map((item) =>
          cell(item, {
            bold: item.includes('->') || item.includes('=>') ? false : item.length < 35,
            shading: item === '->' || item === '=>' ? 'FFFFFF' : 'F5F0E8',
          })
        ),
      })
    ),
  });
  return [table, figureCaption(number, title)];
}

function addStructuredContent(items) {
  for (const item of items) {
    if (item.type === 'h1') docChildren.push(h1(item.text));
    if (item.type === 'h2') docChildren.push(h2(item.text));
    if (item.type === 'h3') docChildren.push(h3(item.text));
    if (item.type === 'p') docChildren.push(para(item.text));
    if (item.type === 'pageBreak') docChildren.push(br());
  }
}

